+package org.apache.streampipes.rest.extensions.management.utils;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+
+public final class EndpointValidator {
+
+  private EndpointValidator() {
+  }
+
+  public static boolean isValid(String endpointUrl) {
+    try {
+      URI endpoint = new URI(endpointUrl);
+
+      if (endpoint.getUserInfo() != null
+          || endpoint.getHost() == null
+          || !("http".equalsIgnoreCase(endpoint.getScheme())
+          || "https".equalsIgnoreCase(endpoint.getScheme()))) {
+        return false;
+      }
+
+      for (InetAddress address : InetAddress.getAllByName(endpoint.getHost())) {
+        if (isLocalAddress(address)) {
+          return false;
+        }
+      }
+
+      return true;
+    } catch (URISyntaxException | UnknownHostException e) {
+      return false;
+    }
+  }
+
+  private static boolean isLocalAddress(InetAddress address) {
+    if (address.isAnyLocalAddress()
+        || address.isLoopbackAddress()
+        || address.isLinkLocalAddress()
+        || address.isSiteLocalAddress()
+        || address.isMulticastAddress()) {
+      return true;
+    }
+
+    byte[] bytes = address.getAddress();
+
+    // IPv6 unique local addresses (fc00::/7)
+    if (bytes.length == 16 && (bytes[0] & 0xfe) == 0xfc) {
+      return true;
+    }
+
+    // Carrier-grade NAT range (100.64.0.0/10)
+    return bytes.length == 4
+        && (bytes[0] & 0xff) == 100
+        && (bytes[1] & 0xc0) == 0x40;
+  }
+}

